from format_lecon import Lesson,paras,table,steps,ABBR,D
from html import escape
import gzip
ABBR.update({'SSO':'Société suisse d’ophtalmologie','ESCRS':'Société européenne de chirurgie de la cataracte et de chirurgie réfractive','OCT':'tomographie par cohérence optique','SARM':'Staphylococcus aureus résistant à la méticilline'})
original=gzip.open(D.parents[1]/'ressources_ia/aips/fi_fr/63029.txt.gz','rt').read().splitlines()
def q(start):
 found=[x for x in original if x.startswith(start)];assert len(found)==1,(start,len(found))
 return '<blockquote><p>« '+escape(found[0])+' »</p></blockquote>'
l=Lesson('Cataracte',2)
preparation=''.join(q(str(i)+'. ') for i in range(1,9))
aprokam=l.subwindow('aprokam','Aprokam : prévention opératoire, dose et préparation',paras('Cette préparation est administrée par le chirurgien dans la chambre antérieure, à la fin de l’opération. Elle prévient une infection ; elle ne fait pas disparaître une cataracte et ne constitue pas le traitement d’une endophtalmie déjà déclarée. Aprokam, Swissmedic 63029, contient 50 mg par flacon, mais la dose injectée après reconstitution est de 1 mg dans 0,1 ml. Le contenu entier du flacon ne doit jamais être injecté dans l’œil.')+
 '<h3>Indication et dose adulte</h3>'+q('Antibioprophylaxie')+q('Voie intra-camérulaire.')+q('La posologie recommandée')+q('NE PAS INJECTER')+q('Aprokam doit être administré par injection intra-oculaire')+
 '<h3>Enfant, sujet âgé, reins et foie</h3>'+q('La sécurité et la posologie')+q("L'adaptation de la posologie")+q('Considérant la faible dose')+
 '<h3>Contre-indication et risques particuliers</h3>'+q('Hypersensibilité à la céfuroxime')+q('Une prudence particulière')+q('Chez les patients présentant un risque')+q("En l'absence de données suffisantes")+q("L'utilisation de la céfuroxime ne doit")+q('À la concentration de céfuroxime')+
 '<h3>Grossesse et allaitement</h3>'+q("Il n'existe que des données limitées")+q('La céfuroxime est excrétée')+
 '<h3>Préparation aseptique et volume à injecter</h3>'+q('Avant son utilisation, Aprokam')+q("Avant l'injection, la solution")+q('UTILISER UN FLACON PAR PATIENT.')+preparation+q('Seule une solution pour injection')+q('La solution reconstituée doit être inspectée')+q('Après reconstitution, le produit')+q('Après utilisation, jeter')+q('Ce médicament ne doit pas être mélangé')+
 '<h3>Arrêt de l’administration et surveillance</h3>'+paras('Une erreur de concentration, de volume ou une préparation douteuse impose de suspendre l’administration et de vérifier le produit. Une allergie ou un événement oculaire suspect nécessite la prise en charge immédiate adaptée. L’antibioprophylaxie ne dispense ni de l’antisepsie ni du suivi postopératoire.')+q("Très rare (<1/10'000)")+q('Fréquence indéterminée')+q('Les cas de surdosage rapportés'),(30,))
l.add('La {cataracte} est une opacification du cristallin qui dégrade la qualité de l’image. Elle se manifeste habituellement par une gêne progressive, souvent avec éblouissement. La présence d’une opacité ne prouve pas qu’elle explique à elle seule toute la baisse visuelle.',paras('Le cristallin est la lentille naturelle située derrière l’iris. Une cataracte altère sa transparence ; elle ne correspond ni à un voile sur la cornée ni à une maladie de la rétine. Une atteinte des deux yeux peut être asymétrique.',
 'Une cataracte liée à l’âge relève généralement d’un parcours programmé. Les formes traumatiques, pédiatriques ou compliquées nécessitent une appréciation différente. Le contexte et la vitesse d’évolution comptent autant que le mot utilisé pour nommer l’opacité.'),(5,23))
l.add('L’{âge et les facteurs associés} orientent le contexte, sans suffire au diagnostic. Diabète, inflammation oculaire, traumatisme et certains traitements peuvent contribuer à l’opacification. Aucun chiffre de prévalence suisse spécifique n’est déduit ici des données générales des brochures.',paras('L’âge est un facteur majeur, mais une cataracte n’est pas réservée à la personne âgée. Une forme précoce justifie de rechercher les antécédents pertinents et une cause particulière. Les traitements prolongés, notamment les corticoïdes, sont recensés sans être arrêtés spontanément.',
 'Le retentissement dépend de la tâche : conduite nocturne, lecture, travail de précision ou autonomie. Deux patients ayant la même acuité mesurée peuvent exprimer des difficultés différentes. L’évaluation préopératoire doit donc intégrer la fonction visuelle et les attentes.'),(23,26,27))
l.add('Les {bases anatomiques} expliquent la chirurgie et ses limites. Le cristallin opacifié est retiré puis remplacé par un implant ; une partie de son enveloppe est habituellement conservée. La qualité finale dépend aussi de la cornée, de la rétine et du nerf optique.',table(['Élément','Rôle ou modification','Conséquence'],[
 ['Cristallin transparent','Transmet et focalise la lumière.','Son opacification réduit la qualité optique, même si un test de lettres reste relativement bon.'],
 ['Capsule cristallinienne','Enveloppe utilisée pour soutenir l’implant lorsque la chirurgie le permet.','Sa partie postérieure peut s’opacifier secondairement.'],
 ['Implant intraoculaire','Remplace la puissance optique du cristallin retiré.','Sa puissance et sa cible réfractive doivent être planifiées ; des lunettes peuvent rester utiles.'],
 ['Macula et voies optiques','Reçoivent et transmettent l’information visuelle.','Une maladie associée peut limiter le gain attendu après extraction.']
])+paras('Une opacification capsulaire postérieure après chirurgie est appelée cataracte secondaire. Le cristallin naturel n’a pas repoussé. Un traitement laser peut ouvrir la capsule lorsque cette opacification explique la gêne et que l’indication est retenue.',
 'Les complications infectieuses, inflammatoires ou rétiniennes obéissent à d’autres mécanismes. Une vision qui baisse après une chirurgie ne doit donc pas être attribuée automatiquement à la capsule.'),(23,24,27,29))
l.add('Le tri recherche une {évolution incompatible avec une cataracte simple}. Douleur, rougeur importante ou perte rapide imposent de reconsidérer le diagnostic. Après chirurgie, une baisse visuelle ou une douleur inhabituelle ne doit pas attendre le contrôle prévu.',paras('🚩 E1 : le parcours urgent du cours général s’applique aux pertes soudaines, rideaux et signes neurologiques. Une cataracte connue peut coexister avec un décollement de rétine ou une autre urgence.',
 'Après opération, une infection intraoculaire, une hypertonie ou une complication rétinienne peut menacer la vision. Le patient contacte sans attendre l’équipe ou les urgences ophtalmologiques en cas de baisse visuelle, rougeur ou douleur inhabituelle. La réception d’un antibiotique prophylactique n’exclut pas l’infection.',
 'Une cataracte infantile ne suit pas le calendrier de convenance d’un adulte : le développement visuel exige un avis spécialisé rapide. Les indications pédiatriques et leurs traitements ne se déduisent pas des protocoles adultes.'),(4,23,25,30))
l.add('L’anamnèse précise le {retentissement fonctionnel et le risque opératoire}. Elle cherche ce que la personne ne peut plus faire, puis les maladies et traitements qui modifient le parcours. Les attentes doivent être discutées avant de choisir l’implant.',steps('Décrire gêne de jour et de nuit, éblouissement, lecture, conduite et activités, avec leur évolution.','Recenser pathologies rétiniennes, glaucome, inflammation, traumatisme, chirurgie réfractive et interventions oculaires antérieures.','Apporter la liste complète des traitements et des allergies ; signaler une infection récente. Ne pas décider seul d’arrêter un anticoagulant.','Discuter la capacité à rester installé, l’anxiété et les besoins de communication. Adapter le parcours d’anesthésie.','Vérifier accompagnement, aide aux gouttes, accès au suivi et souhaits de vision de loin ou de près.'),(23,26,28))
l.add('L’examen établit la {concordance entre opacité et handicap visuel}. Il mesure la vision et examine le cristallin à la lampe à fente. Il recherche aussi une maladie associée susceptible de modifier l’indication ou le bénéfice attendu.',paras('Comparer chaque œil avec la correction adaptée. Décrire l’opacité, mais ne pas limiter l’évaluation à sa présence. Une baisse plus importante qu’attendu appelle un bilan complémentaire.',
 'Examiner cornée, segment antérieur, pression et fond d’œil selon la situation. Une visibilité limitée du fond d’œil doit être consignée. L’équipe choisit alors les examens utiles pour apprécier la rétine et le pronostic.',
 'L’évaluation de la vision utile inclut la gêne lumineuse et les activités. Une bonne lecture de lettres dans une salle ne résume pas la conduite nocturne ou les difficultés quotidiennes.'),(23,26,27))
l.add('L’{approche syndromique} sépare cataracte, maladie associée et complication après chirurgie. La même plainte de flou peut relever de parcours différents. Le moment d’apparition et l’examen orientent la décision.',table(['Présentation','Question principale','Suite'],[
 ['Flou progressif et éblouissement avec cristallin opaque','L’opacité explique-t-elle le handicap ?','Bilan fonctionnel et discussion du traitement.'],
 ['Baisse visuelle disproportionnée','Existe-t-il une maladie maculaire, cornéenne ou du nerf optique ?','Examens dirigés avant promesse de résultat.'],
 ['Baisse brutale ou œil douloureux','Une urgence se superpose-t-elle ?','Évaluation urgente selon le cours général.'],
 ['Dégradation après l’opération','Infection, inflammation, pression, rétine ou autre complication ?','Avis rapide, immédiat si signe d’alarme.'],
 ['Flou tardif avec opacité capsulaire','La capsule explique-t-elle réellement la gêne ?','Discussion d’une capsulotomie après examen.']
]),(23,25,27,29))
l.add('Le diagnostic positif est une {opacification cristallinienne caractérisée}. L’indication de chirurgie est une décision supplémentaire, fondée sur son retentissement et le rapport bénéfice-risque. Un seuil isolé d’acuité ne résume pas cette décision.',paras('L’examen à la lampe à fente établit l’opacité. La discussion relie ce constat aux difficultés du patient et aux autres causes de baisse visuelle. Elle peut conclure à une surveillance lorsque le retentissement reste limité.',
 'Les recommandations européennes soulignent la décision partagée et les bénéfices attendus. Les passages de l’institut britannique NICE consultés demandent de ne pas refuser l’accès à la chirurgie sur la seule acuité. Cela ne signifie pas que toute opacité doit être opérée ni qu’aucun risque ne doit être considéré.'),(23,26,27))
l.add('Le {bilan avant chirurgie} prépare l’implant et identifie les limites du résultat. Il ne remplace pas le diagnostic clinique. Les examens supplémentaires sont guidés par la question oculaire ou anesthésique.',
 '<h3>9.a — Référence diagnostique</h3>'+paras('L’examen ophtalmologique relie l’opacité du cristallin à la plainte. La biométrie n’est pas le test qui prouve une cataracte : elle sert à préparer la puissance de l’implant.')+
 '<h3>9.b — Première intention</h3>'+paras('Mesurer la vision et réaliser les mesures nécessaires au calcul de l’implant. Vérifier l’œil à opérer, les données utilisées et la cible visuelle choisie. Une ancienne chirurgie réfractive modifie l’interprétation de certaines mesures et doit être connue de l’équipe.')+
 '<h3>9.c — Examens dirigés</h3>'+paras('Une tomographie par cohérence optique (OCT) est utile si une atteinte maculaire est suspectée ou si la vision est plus basse que ne le laisse attendre la cataracte. L’étude cornéenne est adaptée notamment à l’astigmatisme et au choix de l’implant. Le bilan anesthésique dépend du terrain.')+
 '<h3>9.d — Seconde intention</h3>'+paras('Si l’examen est limité par l’opacité ou si les résultats sont discordants, préciser les investigations nécessaires et leurs limites pronostiques. La stratégie est réévaluée après résultats ; ne pas annoncer une vision normale garantie quand le fond d’œil n’a pas pu être correctement apprécié.'),(23,26,27,28))
l.add('L’{arbre décisionnel} relie handicap, bénéfice attendu et préparation. La chirurgie est planifiée lorsque l’indication est retenue avec le patient. Toute complication suspectée quitte ce parcours programmé.',steps('Si perte soudaine, douleur ou signe postopératoire inquiétant, alors obtenir une évaluation urgente.','Si opacité confirmée, alors déterminer son retentissement et rechercher les maladies associées.','Si gêne limitée et absence de complication, alors discuter adaptation optique et surveillance.','Si chirurgie indiquée, alors préparer biométrie, cible réfractive, anesthésie, traitements et soutien à domicile.','Après intervention, alors appliquer l’ordonnance personnalisée et les rendez-vous, avec un contact d’urgence connu.','Si baisse tardive, alors rechercher la cause avant de proposer laser ou changement de lunettes.'),(23,25,26,27,28,29))
l.add('Le {traitement de la cataracte} consiste à remplacer le cristallin opacifié lorsque l’indication opératoire est retenue. L’équipe organise prévention infectieuse, soins et suivi. Ni la chirurgie ni le choix d’un implant ne garantissent l’absence future de lunettes.',
 '<h3>11.A — But</h3>'+paras('Améliorer la vision utile et l’autonomie avec un risque acceptable, en tenant compte de la santé des deux yeux. Une décision partagée documente les attentes et les limites prévisibles.')+
 '<h3>11.B — Moyens</h3>'+paras('La chirurgie retire le contenu cristallinien opacifié et met en place un implant. L’anesthésie et la technique sont choisies selon le patient et l’œil. Le laser n’est pas une garantie générale de meilleur résultat.',
 'Le choix de l’implant tient compte des distances utiles, de l’astigmatisme, des maladies associées et de la tolérance aux effets optiques. Les Hôpitaux universitaires de Genève (HUG) décrivent la possibilité d’implants multifocaux ; leurs compromis et éventuels coûts supplémentaires doivent être discutés. Une option plus coûteuse n’est pas automatiquement plus adaptée.',
 'La prophylaxie opératoire associe asepsie, antisepsie et antibiotique intracamérulaire lorsque retenu selon le protocole et les contre-indications. La recommandation européenne de céfuroxime est cohérente avec l’indication suisse d’Aprokam. La dose et les instructions exactes sont détaillées ici : ')+aprokam+paras('Les collyres postopératoires sont prescrits individuellement pour contrôler l’inflammation et prévenir les complications. Le patient reçoit une ordonnance avec produit, œil, fréquence, durée et éventuelle décroissance. Ne pas reprendre un ancien flacon ni transposer automatiquement le traitement d’un autre patient.',
 'La conduite des traitements habituels et le jeûne suivent les instructions de l’équipe d’anesthésie et du chirurgien. L’information générale ne remplace pas ces consignes individualisées. L’accompagnement et l’aide à l’instillation sont organisés avant la sortie.')+
 '<h3>11.C — Surveillance</h3>'+paras('Les HUG prévoient dans leur parcours un examen le lendemain, puis un contrôle dans la semaine et l’adaptation optique ultérieure. Le calendrier peut être ajusté au risque et à l’évolution ; il doit être communiqué explicitement. Une baisse visuelle, une rougeur ou une douleur inhabituelle déclenche un contact urgent sans attendre ce calendrier.',
 'Ne pas frotter ni comprimer l’œil. Suivre les consignes de protection et d’activités, et vérifier la technique des gouttes. La reprise de la conduite est décidée avec l’ophtalmologue selon la récupération, sans présumer qu’une date fixe convient à tous.')+
 '<h3>11.D — Pronostic et suivi</h3>'+paras('Le gain dépend de l’état de la rétine, de la cornée et du nerf optique ainsi que de l’évolution postopératoire. Une opacification capsulaire peut nécessiter plus tard un laser, mais l’indication suppose qu’elle explique la plainte. Après ce geste aussi, douleur, baisse de vision, flashes ou rideau nécessitent une réévaluation.'),(24,25,27,28,29,30))
l.add('La {prévention des complications} commence avant l’intervention et se poursuit à domicile. Elle associe vérification des traitements, hygiène et accès rapide aux soins. Un antibiotique prophylactique réduit un risque sans le supprimer.',paras('Le patient signale allergies et infection récente, apporte sa liste de médicaments et suit les consignes reçues. L’équipe vérifie les mesures de l’implant et la préparation des produits. Une dilution erronée d’un antibiotique peut elle-même léser l’œil.',
 'Laver les mains avant les soins, éviter le contact de l’embout avec l’œil et suivre l’ordonnance. Les difficultés pratiques, visuelles ou cognitives doivent conduire à prévoir une aide. L’information de sortie doit permettre de reconnaître les signes d’alarme et de joindre un service.',
 'La réduction du tabagisme et la protection contre les traumatismes et les ultraviolets relèvent de la prévention générale. Elles ne rendent pas transparent un cristallin déjà opacifié et ne remplacent pas le traitement indiqué.'),(23,25,28,30))
l.add('Les {points clés} sont le handicap réel, la préparation et le suivi. Le diagnostic d’opacité et la décision d’opérer sont deux étapes distinctes. Toute baisse postopératoire inexpliquée doit être évaluée.',steps('Confirmer l’opacité et apprécier sa responsabilité dans la gêne.','Rechercher les maladies qui limitent le bénéfice attendu.','Discuter cible visuelle, implant et éventuel besoin de lunettes.','Respecter la voie, la dose et la préparation de l’antibioprophylaxie opératoire.','Distinguer prophylaxie et traitement d’une infection déclarée.','Donner ordonnance, rendez-vous et contact d’urgence utilisables.','Ne pas attribuer automatiquement une baisse tardive à une cataracte secondaire.'),(23,24,25,27,29,30))
l.quiz([
 ('Question 1 — Une cataracte visible explique-t-elle forcément toute la baisse visuelle ?', 'Non. Une maladie rétinienne, cornéenne ou du nerf optique peut coexister. Il faut vérifier la concordance et le bénéfice attendu.'),
 ('Question 2 — Faut-il attendre un seuil unique d’acuité pour discuter la chirurgie ?', 'Non. Le retentissement sur les activités et les risques sont discutés avec le patient. Un nombre isolé ne résume pas la décision.'),
 ('Question 3 — Une douleur nouvelle est-elle typique d’une cataracte simple ?', 'Non. Elle appelle la recherche d’une autre cause ou d’une complication, surtout avec rougeur ou baisse rapide.'),
 ('Question 4 — La biométrie remplace-t-elle la lampe à fente pour diagnostiquer la cataracte ?', 'Non. Elle prépare notamment le calcul de l’implant ; le diagnostic d’opacité reste clinique.'),
 ('Question 5 — Un implant garantit-il de ne plus porter de lunettes ?', 'Non. La cible choisie et les caractéristiques de l’œil déterminent le résultat ; certaines distances peuvent encore demander une correction.'),
 ('Question 6 — Une ancienne chirurgie réfractive est-elle sans intérêt pour le calcul de l’implant ?', 'Non. Elle modifie certaines données optiques et doit être signalée afin d’adapter le calcul.'),
 ('Question 7 — Aprokam traite-t-il une cataracte sans chirurgie ?', 'Non. Il sert à prévenir une endophtalmie dans le cadre opératoire ; il ne dissout pas le cristallin opaque.'),
 ('Question 8 — La dose oculaire correspond-elle aux 50 mg inscrits sur le flacon ?', 'Non. Après la reconstitution prescrite, la dose adulte est de 1 mg dans 0,1 ml, injectée dans la chambre antérieure par le chirurgien. Injecter le contenu entier serait dangereux.'),
 ('Question 9 — Une allergie aux céphalosporines permet-elle d’utiliser la dose habituelle avec simple surveillance ?', 'Non. Cette hypersensibilité figure parmi les contre-indications. Une autre stratégie doit être choisie par l’équipe.'),
 ('Question 10 — Peut-on appliquer automatiquement la dose adulte d’Aprokam chez l’enfant ?', 'Non. La notice indique que la sécurité et la posologie optimale pédiatriques n’ont pas été étudiées. Le parcours spécialisé est nécessaire.'),
 ('Question 11 — Une antibioprophylaxie exclut-elle une endophtalmie postopératoire ?', 'Non. Une baisse visuelle, une douleur ou une rougeur inhabituelle impose un avis urgent malgré la prophylaxie.'),
 ('Question 12 — Une baisse après chirurgie doit-elle attendre le prochain rendez-vous ?', 'Non si elle est nouvelle ou inquiétante. Le patient contacte l’équipe ou les urgences selon les consignes reçues.'),
 ('Question 13 — La cataracte secondaire correspond-elle à la repousse du cristallin ?', 'Non. Il s’agit d’une opacification de la capsule postérieure conservée ; un laser peut être indiqué après examen.'),
 ('Question 14 — Un résultat moins bon qu’espéré justifie-t-il d’emblée une capsulotomie ?', 'Non. Il faut identifier la cause et vérifier la responsabilité de la capsule avant de proposer ce geste.')
],(23,24,25,26,27,28,29,30))
l.write()
